import React, { useEffect, useState } from "react";
import api from "./api";

function AttendanceDashboard() {
  const [attendance, setAttendance] = useState([]);
  const [stats, setStats] = useState({
    active_students: 0,
    present: 0,
    absent: 0
  });
  const [status, setStatus] = useState([]);

  const loadData = async () => {
    try {
      const res1 = await api.get("/attendance/");
      setAttendance(res1.data || []);

      const res2 = await api.get("/attendance/stats/");
      setStats(res2.data || {});

      const res3 = await api.get("/attendance/status/");
      setStatus(res3.data || []);

    } catch (error) {
      console.error("Dashboard error:", error);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <div>
      <h2>📊 Dashboard</h2>

      <div style={{ marginBottom: 20 }}>
        <strong>Students:</strong> {stats.active_students} |{" "}
        <strong>Present:</strong> {stats.present} |{" "}
        <strong>Absent:</strong> {stats.absent}
      </div>

      <h3>Today's Status</h3>

      <table border="1" cellPadding="8">
        <thead>
          <tr>
            <th>Name</th>
            <th>Status</th>
          </tr>
        </thead>

        <tbody>
          {status.map((s, i) => (
            <tr key={i}>
              <td>{s.name}</td>
              <td>{s.present ? "✅ Present" : "❌ Absent"}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h3>Recognition Log</h3>

      <table border="1" cellPadding="8">
        <thead>
          <tr>
            <th>Time</th>
            <th>Name</th>
            <th>Confidence</th>
          </tr>
        </thead>

        <tbody>
          {attendance.map((a, i) => (
            <tr key={i}>
              <td>{a.timestamp}</td>
              <td>{a.student}</td>
              <td>{a.confidence ? a.confidence.toFixed(3) : "0.000"}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default AttendanceDashboard;
